const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define New Mexico geometry
  const newMexico = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'New Mexico'))
    .geometry();

  // 2. Function to mask low quality MODIS LST pixels
  function maskLST(image) {
    const qa = image.select('QC_Day');
    const mask = qa.bitwiseAnd(3).lte(1); // Keep only good quality (0,1)
    return image.select('LST_Day_1km').updateMask(mask);
  }

  // 3. Get 2016 data (July 20-27)
  const lst2016 = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate('2016-07-20', '2016-07-28')
    .filterBounds(newMexico)
    .map(maskLST);

  const size2016 = lst2016.size().getInfo();
  console.log(`2016 Images: ${size2016}`);

  if (size2016 === 0) {
    console.log('No data for 2016.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get 2001-2010 average for July 20-27
  let allYears = [];
  for (let year = 2001; year <= 2010; year++) {
    const yearCol = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(`${year}-07-20`, `${year}-07-28`)
      .filterBounds(newMexico)
      .map(maskLST);
    allYears.push(yearCol);
  }

  const lstHistorical = ee.ImageCollection(allYears.flat());
  const sizeHistorical = lstHistorical.size().getInfo();
  console.log(`2001-2010 Images: ${sizeHistorical}`);

  if (sizeHistorical === 0) {
    console.log('No data for 2001-2010.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate means
  const mean2016 = lst2016.mean();
  const meanHistorical = lstHistorical.mean();

  // 6. Check pixel counts
  const count2016 = mean2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: newMexico,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const countHistorical = meanHistorical.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: newMexico,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`2016 Valid Pixels: ${count2016}`);
  console.log(`2001-2010 Valid Pixels: ${countHistorical}`);

  if (count2016 === 0 || countHistorical === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Calculate average LST values (in Kelvin, scale factor 0.02)
  const val2016 = mean2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newMexico,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const valHistorical = meanHistorical.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newMexico,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  if (val2016 === null || valHistorical === null) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert to Celsius (scale factor 0.02, subtract 273.15)
  const temp2016 = val2016 * 0.02 - 273.15;
  const tempHistorical = valHistorical * 0.02 - 273.15;

  console.log(`2016 Mean LST: ${temp2016.toFixed(2)}°C`);
  console.log(`2001-2010 Mean LST: ${tempHistorical.toFixed(2)}°C`);

  // 8. Validate temperature range
  if (temp2016 < -50 || temp2016 > 70 || tempHistorical < -50 || tempHistorical > 70) {
    console.log('Invalid temperature range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Compare
  if (temp2016 > tempHistorical) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
